'use strict';
const $=s=>document.querySelector(s), heroNames=['Элиана','Каэль','Громар','Сильва'], roles=['Защита · Священный орден','Атака · Тёмные эльфы','Здоровье · Орки','Поддержка · Лесной союз'];
const initial=()=>({v:1,silver:120000,gems:2500,energy:120,shards:5,wins:0,stage:1,team:[0,1,2],heroes:heroNames.map((name,i)=>({id:i,name,level:1,rank:4,awake:0,gear:null,copies:0})),items:[],daily:null});
let state;try{state=JSON.parse(localStorage.getItem('rayd-save-v1'))||initial();if(state.v!==1)state=initial()}catch{state=initial()}
let page='hub',battle=null,autoTimer=null,selectedMode=null,toastTimer;
const save=()=>{try{localStorage.setItem('rayd-save-v1',JSON.stringify(state))}catch{toast('Не удалось сохранить: хранилище браузера недоступно')}updateResources()};
function updateResources(){['silver','gems','energy'].forEach(k=>$('#'+k).textContent=state[k].toLocaleString('ru-RU'));$('#playerLevel').textContent=1+Math.floor(state.wins/3)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function close(){ $('#modal').hidden=true;$('#modal').innerHTML='' }
function modal(html){$('#modal').innerHTML='<section class="modalbox" role="dialog" aria-modal="true" aria-label="Игровое окно"><button class="close" data-close aria-label="Закрыть">×</button>'+html+'</section>';$('#modal').hidden=false;$('#modal .close').focus()}
const head=(label,title,desc,right='')=>`<div class="pagehead"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`;
const stats=h=>({hp:900+h.level*110+h.rank*100+h.awake*150+(h.gear?300:0),atk:120+h.level*20+h.rank*25+h.awake*30+(h.gear?75:0),def:60+h.level*12+(h.gear?50:0)});
const power=()=>state.team.reduce((s,i)=>s+stats(state.heroes[i]).hp+stats(state.heroes[i]).atk*4,0);
const img=(id,cls='',alt=heroNames[id]||'Босс')=>`<img class="${cls}" src="assets/hero-${id}.webp" alt="${alt}">`;
const tabs=[['hub','⌂','Крепость'],['heroes','♜','Герои'],['battle','⚔','Сражения'],['summon','◈','Призыв'],['shop','♛','Магазин']];
function render(){updateResources();$('#nav').innerHTML=tabs.map(([id,icon,text])=>`<button data-go="${id}" class="${page===id?'active':''}"><span class="navicon" aria-hidden="true">${icon}</span>${text}</button>`).join('');const v=$('#view');if(page==='hub')v.innerHTML=hub();if(page==='heroes')v.innerHTML=heroes();if(page==='battle')v.innerHTML=modes();if(page==='summon')v.innerHTML=summonPage();if(page==='shop')v.innerHTML=shop();if(page==='inventory')v.innerHTML=inventory();if(page==='fight'&&battle)renderFight();v.scrollTop=0}
function navigate(p){if(battle&&!battle.done){toast('Завершите бой или нажмите «Отступить»');return}close();page=p;render()}
function hub(){return `<div class="hub"><div class="brand"><h1>RAYD</h1><small>SHADOW REALM</small></div><div class="hub-title"><h2>КРЕПОСТЬ</h2><small>ВАША ЛЕГЕНДА НАЧИНАЕТСЯ ЗДЕСЬ</small></div><aside class="side"><button class="event" data-daily><span class="eyebrow">ПОДАРОК ДНЯ</span><b>Наследие королевства</b><small>Забрать награду →</small></button><button class="event purple" data-go="summon"><span class="eyebrow">ПОРТАЛ ПРИЗЫВА</span><b>Призови свою легенду</b><small>${state.shards} священных осколков →</small></button></aside><button class="hotspot portal" data-go="summon">Портал<small>ПРИЗЫВ ГЕРОЕВ</small></button><button class="hotspot tavern" data-go="heroes">Таверна<small>РАЗВИТИЕ ГЕРОЕВ</small></button><button class="hotspot forge" data-go="inventory">Кузница<small>АРТЕФАКТЫ И ЭКИПИРОВКА</small></button><button class="hotspot arena" data-mode="arena">Арена<small>ИСПЫТАЙТЕ СВОЙ ОТРЯД</small></button><button class="queststrip" data-quests><span class="sigil">♜</span><span><b>Путь чемпиона</b><small>${Math.min(state.wins,3)} / 3 победы · Награда: 10 осколков</small></span><span style="margin-left:auto;color:var(--gold)">›</span></button><div class="battle-cta"><button class="gold" data-go="battle">В БОЙ <span aria-hidden="true">⚔</span></button><small>Кампания · Подземелья · Боссы</small></div></div>`}
function heroCard(h){return `<button class="hero-card" data-hero="${h.id}">${img(h.id,'portrait')}<span class="rarity">${h.id===1?'ЛЕГЕНДАРНЫЙ':'ЭПИЧЕСКИЙ'}</span>${state.team.includes(h.id)?'<span class="teamtag">В ОТРЯДЕ</span>':''}<div class="cardfoot"><span class="stars">${'★'.repeat(h.rank)}</span><b>${h.name}</b><small>${roles[h.id]} · Ур. ${h.level}/60</small></div></button>`}
function heroes(){return `<section class="page">${head('КОЛЛЕКЦИЯ ЧЕМПИОНОВ','Герои','Соберите отряд. Усильте каждого. Измените исход битвы.',`<span class="tag">Сила отряда: ${power().toLocaleString('ru-RU')}</span>`)}<div class="toolbar"><input id="search" aria-label="Поиск героя" placeholder="Поиск героя…"><select id="filter" aria-label="Фильтр героев"><option value="all">Все герои</option><option value="team">В отряде</option><option value="legend">Легендарные</option></select><button class="outline" data-team>Состав отряда</button></div><div class="cards" id="heroGrid">${state.heroes.map(heroCard).join('')}</div></section>`}
function heroDetail(id){const h=state.heroes[id],s=stats(h);modal(`<div class="herodetail">${img(id)}<div><div class="eyebrow">${id===1?'ЛЕГЕНДАРНЫЙ':'ЭПИЧЕСКИЙ'} ГЕРОЙ</div><h1>${h.name}</h1><span class="stars">${'★'.repeat(h.rank)}</span><p>${roles[id]}<br>Уровень ${h.level}/60 · Возвышение ${h.awake}/6</p><div class="stats"><span>Здоровье <b>${s.hp}</b></span><span>Атака <b>${s.atk}</b></span><span>Защита <b>${s.def}</b></span><span>Скорость <b>${100+id*7}</b></span></div><p class="help">${['Свет возмездия: удар по врагу. Благословение восстанавливает здоровье отряда.','Тёмная стрела: удар по врагу. Буря Бездны наносит двойной урон.','Раскол: мощный удар. Каменная кожа даёт отряду щит.','Точный выстрел: удар по врагу. Лесное исцеление восстанавливает здоровье.'][id]}</p><div class="actions"><button class="gold" data-upgrade="${id}" ${h.level>=60?'disabled':''}>Улучшить · ${h.level*1000} ◉</button><button data-rank="${id}" ${h.rank>=6?'disabled':''}>Ранг + · 50 000 ◉</button><button data-awake="${id}" ${h.awake>=6?'disabled':''}>Возвысить · 100 ◆</button><button data-toggle-team="${id}">${state.team.includes(id)?'Убрать из отряда':'В отряд'}</button><button data-equip="${id}">${h.gear?'Заменить артефакт':'Экипировать'}</button></div><p class="help">Артефакт: ${h.gear||'не надет'} · Копий: ${h.copies}</p></div></div>`)}
function modes(){return `<section class="page">${head('КАРТА ПРИКЛЮЧЕНИЙ','Сражения','Три пути к славе. Один непобедимый отряд.',`<span class="tag">${state.wins} побед · Этап ${state.stage}</span>`)}<div class="modecards"><button class="mode" data-mode="campaign"><img src="assets/bastion.webp" alt="Кампания в королевстве"><div><span class="eyebrow">12 ГЛАВ · РАСТУЩАЯ СЛОЖНОСТЬ</span><h2>Кампания</h2><p>Освободите земли от армии тьмы</p><span class="gold">Продолжить · 6 ϟ</span></div></button><button class="mode" data-dungeons>${img(4,'','Дракон в подземелье')}<div><span class="eyebrow">ЛЕГЕНДАРНЫЕ АРТЕФАКТЫ</span><h2>Подземелья</h2><p>Дракон и Ледяной король ждут вас</p><span class="gold">Выбрать босса · 10 ϟ</span></div></button><button class="mode" data-mode="arena">${img(2)}<div><span class="eyebrow">СОПЕРНИК ПОД УПРАВЛЕНИЕМ ИИ</span><h2>Арена</h2><p>Сражайтесь за самоцветы и славу</p><span class="gold">Найти бой · 5 ϟ</span></div></button></div></section>`}
function dungeons(){modal(`<div class="eyebrow">ПОДЗЕМЕЛЬЯ</div><h1>Выберите испытание</h1><div class="modecards" style="grid-template-columns:1fr 1fr"><button class="mode" data-mode="dragon">${img(4,'','Дракон')}<div><h2>Логово дракона</h2><p>Огненное дыхание · Артефакт атаки</p><span class="gold">Войти · 10 ϟ</span></div></button><button class="mode" data-mode="ice">${img(5,'','Ледяной король')}<div><h2>Ледяной престол</h2><p>Ледяная ярость · Артефакт защиты</p><span class="gold">Войти · 10 ϟ</span></div></button></div>`)}
function teamDialog(mode){selectedMode=mode||null;modal(`<div class="eyebrow">ПОДГОТОВКА ОТРЯДА</div><h1>${mode?modeName(mode):'Ваши чемпионы'}</h1><p>Выберите от 1 до 3 героев. Нажмите на портрет, чтобы изменить состав.</p><div class="roster">${state.heroes.map(h=>`<button class="${state.team.includes(h.id)?'selected':''}" data-team-select="${h.id}">${img(h.id)}<b>${h.name} · ${h.level} ур.</b></button>`).join('')}</div><p class="help">Сила: ${power()} · В отряде: ${state.team.length}/3. ${mode==='campaign'?`Глава ${Math.ceil(state.stage/3)} · Этап ${state.stage}/36`:''}</p><button class="gold" ${state.team.length===0?'disabled':''} ${mode?'data-start="'+mode+'"':'data-close'}>${mode?'Начать бой · '+cost(mode)+' ϟ':'Сохранить отряд'}</button>`)}
const cost=m=>m==='campaign'?6:m==='arena'?5:10;
const modeName=m=>({campaign:'Кампания',dragon:'Логово дракона',ice:'Ледяной престол',arena:'Арена'})[m];
function summonPage(){return `<section class="page">${head('ДРЕВНЯЯ МАГИЯ','Портал призыва','Осколок открывает путь новому союзнику.',`<span class="tag">Осколки: ${state.shards}</span>`)}<div class="summon"><div class="summon-portal"><img src="assets/bastion.webp" alt="Синий портал призыва"></div><div><div class="eyebrow">СВЯЩЕННЫЙ ПРИЗЫВ</div><h1>Сила за гранью света</h1><p>Призовите чемпиона и пробудите силу своего отряда.</p><p class="chance">Эпический герой — 75% · Легендарный — 25%<br>Повтор героя: +1 копия и +2 уровня, максимум 60.</p><div class="actions"><button class="gold" data-summon ${state.shards<1?'disabled':''}>Призвать · 1 осколок</button><button class="outline" data-go="shop">Получить осколки бесплатно</button></div></div></div></section>`}
function doSummon(){if(state.shards<1)return toast('Заберите осколки в магазине');state.shards--;const id=Math.floor(Math.random()*4),h=state.heroes[id];h.copies++;h.level=Math.min(60,h.level+2);save();render();modal(`<div class="result"><div class="eyebrow">ПРИЗЫВ ЗАВЕРШЁН</div><h1>${h.name}</h1><img src="assets/hero-${id}.webp" alt="${h.name}" style="height:220px;border:2px solid var(--gold)"><p>${id===1?'Легендарный':'Эпический'} чемпион · Получена копия<br>Уровень героя повышен: ${h.level}/60</p><button class="gold" data-summon ${state.shards<1?'disabled':''}>Призвать ещё · 1 осколок</button></div>`)}
const packs=[['legend','◈','Священный набор','10 осколков для призыва чемпионов','10 осколков'],['rich','◆','Сокровища королевства','10 000 самоцветов и 1 000 000 серебра','Самоцветы и серебро'],['energy','ϟ','Бесконечный поход','500 энергии для новых приключений','500 энергии'],['gear','⚔','Арсенал легенд','3 артефакта: оружие, доспех и амулет','3 артефакта'],['level','♜','Мастерская опыта','Всем героям +5 уровней, максимум 60','Опыт всему отряду'],['all','♛','Королевский дар','Все наборы ресурсов в одном подарке','Осколки, валюта и энергия']];
function shop(){return `<section class="page">${head('ЩЕДРОСТЬ БЕЗ ГРАНИЦ','Магазин','Все предложения бесплатны. Забирайте повторно без ограничений.',`<span class="tag">ВСЕГДА 0 ₽</span>`)}<div class="shopgrid">${packs.map(([id,art,name,desc,loot])=>`<article class="pack"><span class="eyebrow">ПОДАРОК КОРОЛЕВСТВА</span><img class="packart" src="assets/item-${id==='gear'?2:id==='rich'?1:0}.webp" alt="${name}"><h2>${name}</h2><p>${desc}</p><button class="gold" data-pack="${id}">Забрать · 0 ₽</button><small>${loot} · Без оплаты</small></article>`).join('')}</div></section>`}
function pack(id){if(['legend','all'].includes(id))state.shards+=10;if(['rich','all'].includes(id)){state.silver+=1000000;state.gems+=10000}if(['energy','all'].includes(id))state.energy+=500;if(id==='gear')for(const name of ['Клинок заката','Доспех стража','Амулет Бездны'])state.items.push({id:Date.now()+Math.random(),name,stars:6});if(id==='level')state.heroes.forEach(h=>h.level=Math.min(60,h.level+5));save();toast('Подарок получен! '+packs.find(p=>p[0]===id)[4]);render()}
function inventory(){return `<section class="page">${head('КУЗНИЦА КОРОЛЕВСТВА','Артефакты','Каждый артефакт даёт +300 здоровья, +75 атаки и +50 защиты.',`<button class="outline" data-go="shop">Бесплатный арсенал</button>`)}${state.items.length?`<div class="inventory">${state.items.map((it,i)=>`<div class="item"><span class="stars">★★★★★★</span><h3 style="margin-top:10px">${it.name}</h3><small>Здоровье +300 · Атака +75 · Защита +50</small><button data-item="${i}">Экипировать</button></div>`).join('')}</div>`:'<p>Здесь появятся трофеи из подземелий. Также можно забрать артефакты в бесплатном магазине.</p>'}</section>`}
function equipHero(id){if(!state.items.length){toast('Нет артефактов. Заберите «Арсенал легенд» в магазине');return}const h=state.heroes[id],it=state.items.shift();if(h.gear)state.items.push({id:Date.now(),name:h.gear,stars:6});h.gear=it.name;save();heroDetail(id);toast('Надет артефакт: '+it.name)}
function start(mode){if(state.team.length<1)return toast('Выберите хотя бы одного героя');if(state.energy<cost(mode))return toast('Не хватает энергии. Магазин выдаёт её бесплатно');stopAuto();state.energy-=cost(mode);save();const factor=mode==='campaign'?1+(state.stage-1)*.14:mode==='arena'?1.35:2;const hp=Math.round(2900*factor);battle={mode,allies:state.team.map(id=>{const h=state.heroes[id],s=stats(h);return {id,name:h.name,hp:s.hp,max:s.hp,atk:s.atk,def:s.def,cd:0,shield:0}}),enemy:{id:mode==='dragon'?4:mode==='ice'?5:mode==='arena'?2:5,name:mode==='dragon'?'Вархаг, Пепельный дракон':mode==='ice'?'Мортис, Ледяной король':mode==='arena'?'Громар · Защитник арены':'Страж тьмы',hp,max:hp,atk:Math.round(180*factor)},turn:0,round:1,log:'Выберите способность активного героя',done:false,busy:false,auto:false};close();page='fight';render()}
function fighter(f,enemy=false,active=false){return `<div class="fighter ${enemy?'enemy':''} ${active?'active':''} ${f.hp<=0?'dead':''}" id="fighter-${enemy?'enemy':f.id}">${img(f.id,'',f.name)}<div class="hp"><span style="width:${Math.max(0,f.hp/f.max*100)}%"></span></div><b>${f.name}</b><small>${Math.max(0,Math.ceil(f.hp))} / ${f.max}${f.shield?' · Щит':''}</small></div>`}
function renderFight(){const b=battle;if(!b)return;const a=b.allies[b.turn];$('#view').innerHTML=`<div class="battle"><div class="battlehead"><button class="outline" data-retreat>‹ Отступить</button><div style="text-align:center"><span class="eyebrow">${modeName(b.mode).toUpperCase()}</span><h2>${b.enemy.name}</h2></div><span class="tag">Раунд ${b.round}</span></div><div class="combatants"><div class="allies">${b.allies.map((f,i)=>fighter(f,false,i===b.turn)).join('')}</div>${fighter(b.enemy,true)}</div><div class="battlebar"><div class="battlelog"><b style="color:var(--gold)">${a.name}</b><br>${b.log}</div><div class="skills"><button class="skill" data-skill="attack" ${b.busy?'disabled':''}><b>⚔ Удар</b><small>Базовая атака</small></button><button class="skill" data-skill="special" ${b.busy||a.cd?'disabled':''}><b>${a.id===1?'Буря Бездны':a.id===2?'Каменная кожа':'Исцеление'}</b><small>${a.cd?'Перезарядка: '+a.cd:'Особая способность'}</small></button><button class="skill" data-auto><b>Автобой ${b.auto?'●':'○'}</b><small>${b.auto?'Остановить':'Включить'}</small></button></div></div></div>`}
function floatDamage(target,n){const el=$('#fighter-'+target);if(!el)return;el.classList.add('hit');const d=document.createElement('span');d.className='damage';d.textContent=n;el.append(d)}
function action(type){const b=battle;if(!b||b.done||b.busy||document.visibilityState==='hidden'||matchMedia('(orientation:portrait)').matches)return;const a=b.allies[b.turn];if(type==='special'&&a.cd)return;b.busy=true;let damage=0;if(type==='special'){a.cd=3;if(a.id===1){damage=Math.round(a.atk*2.7);b.enemy.hp-=damage;b.log='Буря Бездны наносит '+damage+' урона'}else if(a.id===2){b.allies.filter(f=>f.hp>0).forEach(f=>f.shield=2);damage=Math.round(a.atk*.8);b.enemy.hp-=damage;b.log='Отряд получил щит на 2 атаки босса'}else{b.allies.filter(f=>f.hp>0).forEach(f=>f.hp=Math.min(f.max,f.hp+Math.round(f.max*.3)));b.log='Отряд восстановил 30% здоровья';damage=Math.round(a.atk*.5);b.enemy.hp-=damage}}else{damage=Math.round(a.atk*(.9+Math.random()*.3));b.enemy.hp-=damage;b.log=a.name+' наносит '+damage+' урона'}renderFight();floatDamage('enemy','−'+damage);setTimeout(()=>{if(b!==battle||b.done)return;if(b.enemy.hp<=0){finish(true);return}let next=b.turn+1;while(next<b.allies.length&&b.allies[next].hp<=0)next++;if(next>=b.allies.length){b.round++;const alive=b.allies.filter(f=>f.hp>0),aoe=b.mode==='dragon'&&b.round%3===0;const targets=aoe?alive:[alive[Math.floor(Math.random()*alive.length)]];targets.forEach(f=>{const dmg=Math.max(30,Math.round((b.enemy.atk-f.def*.3)*(f.shield?.5:1)));f.hp=Math.max(0,f.hp-dmg);if(f.shield)f.shield--;});b.log=aoe?'Огненное дыхание поражает весь отряд!':'Враг атакует '+targets[0].name;b.allies.forEach(f=>f.cd=Math.max(0,f.cd-1));if(!b.allies.some(f=>f.hp>0)){finish(false);return}next=b.allies.findIndex(f=>f.hp>0)}b.turn=next;b.busy=false;renderFight()},550)}
function stopAuto(){clearInterval(autoTimer);autoTimer=null;if(battle)battle.auto=false}
function toggleAuto(){if(!battle||battle.done)return;if(battle.auto){stopAuto()}else{battle.auto=true;autoTimer=setInterval(()=>{if(!battle||battle.done){stopAuto();return}const a=battle.allies[battle.turn];action(a.cd?'attack':'special')},1050)}renderFight()}
function finish(win){const b=battle;if(!b||b.done)return;b.done=true;b.busy=false;stopAuto();let reward=0,item=null;if(win){state.wins++;reward=b.mode==='campaign'?12000+state.stage*1000:25000;state.silver+=reward;state.gems+=b.mode==='arena'?100:30;state.heroes.filter(h=>state.team.includes(h.id)).forEach(h=>h.level=Math.min(60,h.level+1));if(b.mode==='campaign')state.stage=Math.min(36,state.stage+1);if(['dragon','ice'].includes(b.mode)){item=b.mode==='dragon'?'Клинок дракона':'Доспех Ледяного короля';state.items.push({id:Date.now(),name:item,stars:6})}save()}modal(`<div class="result"><div class="eyebrow">${modeName(b.mode).toUpperCase()}</div><h1>${win?'ПОБЕДА':'ПОРАЖЕНИЕ'}</h1><p>${win?'Тьма отступает. Легенда вашего отряда растёт.':'Усильте героев и экипируйте артефакты перед новой попыткой.'}</p>${win?`<div class="loot">+${reward.toLocaleString('ru-RU')} ◉ &nbsp; +${b.mode==='arena'?100:30} ◆</div><p>Герои отряда: +1 уровень${item?'<br>Артефакт: '+item:''}</p>`:''}<div class="actions" style="justify-content:center"><button class="gold" data-retry="${b.mode}">Ещё бой · ${cost(b.mode)} ϟ</button><button class="outline" data-return>В крепость</button></div></div>`)}
function daily(){const today=new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'});if(state.daily===today)return toast('Награда получена. Возвращайтесь завтра!');state.daily=today;state.gems+=500;state.shards+=3;state.energy+=100;save();toast('Подарок дня: 500 самоцветов, 3 осколка и 100 энергии');render()}
function quests(){modal(`<div class="eyebrow">ЗАДАНИЯ</div><h1>Путь чемпиона</h1><p>Одержите 3 победы в любом режиме.</p><div class="loot">${Math.min(state.wins,3)} / 3 победы</div><button class="gold" data-quest-claim ${state.wins<3||state.questClaimed?'disabled':''}>${state.questClaimed?'Награда получена':'Забрать 10 осколков'}</button>`)}
function profile(){modal(`<div class="eyebrow">ПРОФИЛЬ</div><h1>Странник</h1><div class="stats"><span>Уровень <b>${1+Math.floor(state.wins/3)}</b></span><span>Победы <b>${state.wins}</b></span><span>Этап кампании <b>${state.stage}/36</b></span><span>Сила отряда <b>${power()}</b></span></div><p>Прогресс автоматически сохраняется в этом браузере. Игра одиночная; на арене сражается ИИ.</p><button class="outline" data-go="heroes">Открыть героев</button>`)}
function settings(){modal(`<div class="eyebrow">НАСТРОЙКИ</div><h1>Теневое королевство</h1><p>Одиночная браузерная RPG с локальным сохранением. Все товары бесплатны.</p><p class="help">На телефоне требуется горизонтальная ориентация. Во время поворота и в скрытой вкладке автобой ставится на паузу. Полный экран доступен через кнопку ⛶.</p><div class="actions"><button class="outline" data-export>Экспорт сохранения</button><button class="outline" data-import>Импорт сохранения</button><button data-reset>Начать заново</button></div><input id="importFile" type="file" accept="application/json" hidden>`)}
function validSave(s){return s&&s.v===1&&['silver','gems','energy','shards','wins','stage'].every(k=>Number.isFinite(s[k])&&s[k]>=0)&&s.stage>=1&&s.stage<=36&&Array.isArray(s.heroes)&&s.heroes.length===4&&s.heroes.every((h,i)=>h.id===i&&h.name===heroNames[i]&&Number.isInteger(h.level)&&h.level>=1&&h.level<=60&&h.rank>=4&&h.rank<=6&&h.awake>=0&&h.awake<=6&&(h.gear===null||typeof h.gear==='string'&&/^[А-Яа-яёЁa-zA-Z0-9 ·-]{1,80}$/.test(h.gear)))&&Array.isArray(s.team)&&s.team.length<=3&&new Set(s.team).size===s.team.length&&s.team.every(i=>Number.isInteger(i)&&i>=0&&i<4)&&Array.isArray(s.items)&&s.items.length<10000&&s.items.every(it=>typeof it.name==='string'&&/^[А-Яа-яёЁa-zA-Z0-9 ·-]{1,80}$/.test(it.name))}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;const d=el.dataset;if('close'in d){if(battle?.done){battle=null;page='hub';render()}close();return}if(d.go){if(d.go==='profile')return profile();if(d.go==='settings')return settings();return navigate(d.go)}if(d.claim){state[d.claim]+=d.claim==='silver'?100000:d.claim==='gems'?1000:100;save();toast('Ресурсы добавлены бесплатно');return}if(d.hero!==undefined)return heroDetail(+d.hero);if(d.upgrade!==undefined){const h=state.heroes[+d.upgrade],price=h.level*1000;if(h.level>=60)return;if(state.silver<price)return toast('Не хватает серебра. Загляните в бесплатный магазин');state.silver-=price;h.level++;save();return heroDetail(h.id)}if(d.rank!==undefined){const h=state.heroes[+d.rank];if(h.rank>=6)return;if(state.silver<50000)return toast('Нужно 50 000 серебра');state.silver-=50000;h.rank++;save();return heroDetail(h.id)}if(d.awake!==undefined){const h=state.heroes[+d.awake];if(h.awake>=6)return;if(state.gems<100)return toast('Нужно 100 самоцветов');state.gems-=100;h.awake++;save();return heroDetail(h.id)}if(d.toggleTeam!==undefined||d.teamSelect!==undefined){const id=+(d.toggleTeam??d.teamSelect);if(state.team.includes(id))state.team=state.team.filter(i=>i!==id);else{if(state.team.length>=3)return toast('Максимум 3 героя. Сначала уберите одного');state.team.push(id)}save();return d.teamSelect!==undefined?teamDialog(selectedMode):heroDetail(id)}if(d.equip!==undefined)return equipHero(+d.equip);if('team'in d)return teamDialog();if(d.mode)return teamDialog(d.mode);if('dungeons'in d)return dungeons();if(d.start)return start(d.start);if('summon'in d)return doSummon();if(d.pack)return pack(d.pack);if(d.item!==undefined){modal(`<h1>Кому передать артефакт?</h1><div class="roster">${state.heroes.map(h=>`<button data-item-equip="${d.item}" data-target="${h.id}">${img(h.id)}<b>${h.name}</b></button>`).join('')}</div>`);return}if(d.itemEquip!==undefined){const it=state.items.splice(+d.itemEquip,1)[0],h=state.heroes[+d.target];if(!it)return;if(h.gear)state.items.push({id:Date.now(),name:h.gear,stars:6});h.gear=it.name;save();close();render();toast('Артефакт экипирован');return}if(d.skill)return action(d.skill);if('auto'in d)return toggleAuto();if('retreat'in d){modal('<h1>Отступить?</h1><p>Потраченная энергия не возвращается.</p><button class="gold" data-return>Покинуть бой</button>');return}if('return'in d){stopAuto();battle=null;page='hub';close();render();return}if(d.retry){battle=null;return teamDialog(d.retry)}if('daily'in d)return daily();if('quests'in d)return quests();if('questClaim'in d){if(state.wins>=3&&!state.questClaimed){state.shards+=10;state.questClaimed=true;save();quests();toast('Получено 10 осколков')}return}if('export'in d){const blob=new Blob([JSON.stringify(state)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='rayd-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return}if('import'in d)return $('#importFile').click();if('reset'in d){modal('<h1>Сбросить прогресс?</h1><p>Герои и награды этого сохранения будут удалены. Сначала можно экспортировать сохранение.</p><button class="gold" data-confirm-reset>Сбросить прогресс</button>');return}if('confirmReset'in d){state=initial();save();close();page='hub';render();toast('Началось новое приключение')}});
document.addEventListener('input',e=>{if(e.target.id==='search')filterHeroes()});document.addEventListener('change',async e=>{if(e.target.id==='filter')filterHeroes();if(e.target.id==='importFile'&&e.target.files[0]){try{const s=JSON.parse(await e.target.files[0].text());if(!validSave(s))throw Error();state=s;save();close();page='hub';render();toast('Сохранение загружено')}catch{toast('Некорректный файл сохранения')}}});
function filterHeroes(){const q=$('#search').value.toLowerCase(),f=$('#filter').value;$('#heroGrid').innerHTML=state.heroes.filter(h=>h.name.toLowerCase().includes(q)&&(f==='all'||f==='team'&&state.team.includes(h.id)||f==='legend'&&h.id===1)).map(heroCard).join('')||'<p>Герои не найдены</p>'}
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();if(screen.orientation?.lock)await screen.orientation.lock('landscape')}catch{toast('Полный экран недоступен в этом браузере. Поверните устройство вручную')}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').hidden){if(battle?.done){battle=null;page='hub';render()}close()}if(e.key==='Tab'&&!$('#modal').hidden){const els=[...$('#modal').querySelectorAll('button:not(:disabled),input:not([hidden]),select')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
